package app.mightymorphing.extension.joey;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Color;
import android.util.Base64;

import java.util.HashMap;

/** The seven splash characters. A colour shift keeps the face and moves the hue. */
final class SplashArt {
    static final String PLAIN = "";
    static final String HEADPHONES = "";
    static final String GLASSES = "";
    static final String FLOWER = "";
    static final String LEAF = "";
    static final String BAMBOO = "";
    static final String SPARK = "";
    private static final HashMap<String, Bitmap> CACHE = new HashMap<String, Bitmap>();
    private static final HashMap<String, Float> HUE = new HashMap<String, Float>();

    private SplashArt() {
    }

    static Bitmap character(String key) {
        Bitmap cached = CACHE.get(key);
        if (cached != null && !cached.isRecycled()) return cached;
        String data = PLAIN;
        if ("headphones".equals(key)) data = HEADPHONES;
        else if ("glasses".equals(key)) data = GLASSES;
        else if ("flower".equals(key)) data = FLOWER;
        else if ("leaf".equals(key)) data = LEAF;
        else if ("bamboo".equals(key)) data = BAMBOO;
        else if ("spark".equals(key)) data = SPARK;
        try {
            byte[] bytes = Base64.decode(data, Base64.DEFAULT);
            Bitmap bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            if (bitmap != null) CACHE.put(key, bitmap);
            return bitmap;
        } catch (Throwable ignored) {
            return null;
        }
    }

    static Bitmap recolor(String key, int target) {
        Bitmap source = character(key);
        if (source == null) return null;
        float[] to = new float[3];
        Color.colorToHSV(target, to);
        float from = sourceHue(key, source);
        if (to[1] < 0.12f) return desaturate(source);
        // The plain koala is already near Aqua, so the small-shift skip would leave the original seafoam.
        if ((target & 0x00FFFFFF) == 0x003DBFB2) return tintNear(source, to);
        if (Math.abs(wrap(to[0] - from)) < 8f) return source;
        return shift(source, to[0] - from);
    }

    private static float sourceHue(String key, Bitmap source) {
        Float known = HUE.get(key);
        if (known != null) return known;
        int w = source.getWidth();
        int h = source.getHeight();
        int[] pixels = new int[w * h];
        source.getPixels(pixels, 0, w, 0, 0, w, h);
        float bestSat = 0f;
        float hue = 180f;
        float[] hsv = new float[3];
        for (int pixel : pixels) {
            if (Color.alpha(pixel) < 200) continue;
            Color.colorToHSV(pixel, hsv);
            if (hsv[2] < 0.35f || hsv[2] > 0.9f) continue;
            if (hsv[1] > bestSat) {
                bestSat = hsv[1];
                hue = hsv[0];
            }
        }
        HUE.put(key, hue);
        return hue;
    }

    /** Fur already painted near Aqua takes the Aqua hue and saturation. Ears, eyes, and muzzle stay. */
    private static Bitmap tintNear(Bitmap source, float[] to) {
        int w = source.getWidth();
        int h = source.getHeight();
        int[] pixels = new int[w * h];
        source.getPixels(pixels, 0, w, 0, 0, w, h);
        float[] hsv = new float[3];
        for (int i = 0; i < pixels.length; i++) {
            int pixel = pixels[i];
            if (Color.alpha(pixel) < 8) continue;
            Color.colorToHSV(pixel, hsv);
            if (hsv[2] < 0.2f || hsv[1] < 0.15f) continue;
            if (Math.abs(wrap(hsv[0] - to[0])) > 55f) continue;
            hsv[0] = to[0];
            hsv[1] = to[1];
            pixels[i] = Color.HSVToColor(Color.alpha(pixel), hsv);
        }
        Bitmap out = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        out.setPixels(pixels, 0, w, 0, 0, w, h);
        return out;
    }

    private static Bitmap shift(Bitmap source, float delta) {
        int w = source.getWidth();
        int h = source.getHeight();
        int[] pixels = new int[w * h];
        source.getPixels(pixels, 0, w, 0, 0, w, h);
        float[] hsv = new float[3];
        for (int i = 0; i < pixels.length; i++) {
            int pixel = pixels[i];
            if (Color.alpha(pixel) < 8) continue;
            Color.colorToHSV(pixel, hsv);
            if (hsv[2] < 0.2f) continue;
            if (hsv[1] < 0.08f) continue;
            hsv[0] = (hsv[0] + delta + 360f) % 360f;
            pixels[i] = Color.HSVToColor(Color.alpha(pixel), hsv);
        }
        Bitmap out = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        out.setPixels(pixels, 0, w, 0, 0, w, h);
        return out;
    }

    private static Bitmap desaturate(Bitmap source) {
        int w = source.getWidth();
        int h = source.getHeight();
        int[] pixels = new int[w * h];
        source.getPixels(pixels, 0, w, 0, 0, w, h);
        float[] hsv = new float[3];
        for (int i = 0; i < pixels.length; i++) {
            int pixel = pixels[i];
            if (Color.alpha(pixel) < 8) continue;
            Color.colorToHSV(pixel, hsv);
            if (hsv[2] < 0.2f) continue;
            hsv[1] = hsv[1] * 0.18f;
            pixels[i] = Color.HSVToColor(Color.alpha(pixel), hsv);
        }
        Bitmap out = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        out.setPixels(pixels, 0, w, 0, 0, w, h);
        return out;
    }

    private static float wrap(float delta) {
        float value = delta % 360f;
        if (value > 180f) value -= 360f;
        if (value < -180f) value += 360f;
        return value;
    }
}
